test("トークンを参照しているノードの破線は、そのノード自身の outline として描かれる", () => {
  const document = setupDocument();

  renderCanvas({
    selection: DocumentSelection.fromNames(document, []),
    tokenSelection: selectingGray900(document),
  });

  expect(ruleIndexOf("title", "outline:1.5px dashed")).toBeGreaterThanOrEqual(
    0,
  );
});

test("選択中のノードがそのトークンを参照していても、選択の枠が破線に負けない", () => {
  const document = setupDocument();

  renderCanvas({
    selection: DocumentSelection.fromNames(document, ["title"]),
    tokenSelection: selectingGray900(document),
  });

  expect(ruleIndexOf("title", "dashed #0d99ff")).toBeGreaterThanOrEqual(0);
  expect(ruleIndexOf("title", "solid #3b82f6")).toBeGreaterThan(
    ruleIndexOf("title", "dashed #0d99ff"),
  );
});

test("複数選んでいると選んだものすべてに枠が出る", () => {
  renderCanvas({ selection: setupMultiSelected() });

  const styles = injectedStyles();

  expect(styles).toContain('[data-name="home-login"]{outline:2px solid');
  expect(styles).toContain('[data-name="settings-login"]{outline:2px solid');
});

test("受け入れ先の上では、その Box が枠で示される", () => {
  renderCanvas({ selection: setupSelection() });

  pressPointer(drawn("title"), { x: 100, y: 100 });
  movePointer(drawn("panel"), { x: 100, y: 150 });

  expect(injectedStyles()).toContain('[data-name="panel"]{outline:2px dashed');
});

test("測り直すと、幅のハンドルは要素の右辺の上へ置かれる", () => {
  /*
   * 測定 → 描画の配線。ハンドルが出ているだけでは、測った矩形を使わずに置いていても
   * 通ってしまう。器の矩形は happy-dom では 0 なので、client 座標がそのまま
   * 器からの相対になる。右辺 300 の上に中心が来るので、左端は 5px ぶん手前。
   */
  renderCanvas({ selection: setupSelection(["panel"]) });
  drawnAt("panel", PanelBounds);

  fireEvent(globalThis.window, new Event("resize"));

  expect(resizeHandleAt({ x: 1, y: 0.5 }).style.left).toBe("295px");
});

test("測り直すと、90 度回したノードの右辺のハンドルは回った右辺の中点（画面の下）へ置かれる", () => {
  // 外接矩形の右辺の中点なら (200, 100)。器の矩形は happy-dom では 0
  renderCanvas({ selection: setupSelection() });
  drawnTurned("turned");

  fireEvent(globalThis.window, new Event("resize"));

  const rightEdge = resizeHandleAt({ x: 1, y: 0.5 });
  expect(Number.parseFloat(rightEdge.style.left)).toBeCloseTo(145);
  expect(Number.parseFloat(rightEdge.style.top)).toBeCloseTo(195);
});

/**
 * 名前を指す規則のうち、その宣言を持つものが何番目に差し込まれたか。
 *
 * 同じ選択子・同じ詳細度の規則は後に書いたほうが勝つので、どちらが見えるかは
 * 差し込む順で決まる。happy-dom は CSS を解決しないため、順そのものを見る。
 *
 * @param name 規則が指している artboard / ノードの名前
 * @param declaration 探したい宣言の一部
 * @returns その規則の位置。見つからなければ -1
 */
function ruleIndexOf(name: string, declaration: string): number {
  const styles = [...canvasContent().querySelectorAll("style")];
  return styles.findIndex((style) => {
    const text = style.textContent ?? "";
    return text.includes(`"${name}"`) && text.includes(declaration);
  });
}

export function NameStyleRule({
  name,
  declarations,
}: Readonly<{ name: string; declarations: string }>) {
  return <style>{`${CanvasDom.selectorOf(name)}{${declarations}}`}</style>;
}
